 634	#[cfg(test)]
 635	mod tests {
 636	
 637	    /// M17.5 F-61: `position_free` protects exactly one author-keyed map, so
 638	    /// this locks the schema fact that makes that sufficient — `attributes` is
 639	    /// the only one, and `HirValue` carries no map of its own.
 640	    #[test]
 641	    fn attributes_is_the_only_author_keyed_map_in_the_hir() {
 642	        let schema = include_str!("../../liminal-hir/src/schema.rs");
 643	        // Any visibility, not just `pub`: a `pub(crate)` or private field is
 644	        // serialized the same way and would be just as author-keyed. A field
 645	        // declaration is `name: ...Map<String,` after the visibility; the
 646	        // `&mut` form is a function parameter, not a field. Line-oriented, so
 647	        // a type split across lines would escape — rustfmt keeps these on one.
 648	        let keyed: Vec<&str> = schema
 649	            .lines()
 650	            .map(str::trim)
 651	            .filter(|line| {
 652	                let after_visibility = line
 653	                    .split_once(' ')
 654	                    .filter(|(first, _)| first.starts_with("pub"))
 655	                    .map_or(*line, |(_, rest)| rest);
 656	                after_visibility.contains("Map<String,")
 657	                    && !after_visibility.contains('&')
 658	                    && after_visibility.split_once(": ").is_some_and(|(name, _)| {
 659	                        !name.is_empty() && name.chars().all(|ch| ch.is_alphanumeric() || ch == '_')
 660	                    })
 661	            })
 662	            .collect();
 663	        assert_eq!(
