  64	/// Digests the lane records for a captured scope trace, computed by the same
  65	/// code the gate later judges them with. `kind` is `paths` (the observed
  66	/// open-path set) or `resolved` (traced corpus paths resolved inside the tree).
  67	pub fn scope_trace_digest_repo(
  68	    root: &Utf8Path,
  69	    kind: &str,
  70	    traces: &[Utf8PathBuf],
  71	    scope: &str,
  72	) -> Result<String> {
  73	    anyhow::ensure!(!traces.is_empty(), "scope digest needs at least one trace");
  74	    let label = format!("{scope} corpus scope");
  75	    // The union of open paths: sets, so carving a fuzz binary's lines out of
  76	    // the stage trace into its own part changes nothing the gate judges (F-43).
  77	    let mut open = BTreeSet::new();
  78	    for trace in traces {
  79	        open.extend(scan_scope_trace_file(trace, &label)?.open_paths);
  80	    }
  81	    match kind {
  82	        "paths" => Ok(scope_trace_paths_digest_from(&open)),
  83	        "resolved" => {
  84	            let access = if scope == "fuzz" {
  85	                CorpusAccess::Required
  86	            } else {
  87	                CorpusAccess::IfPresent
  88	            };
  89	            resolved_corpus_paths_digest_from(
  90	                root,
  91	                root.as_str(),
  92	                &open,
  93	                &label,
  94	                access,
  95	                LockedCorpus::WritesOnly,
  96	            )
  97	        }
  98	        other => anyhow::bail!("unknown scope digest kind {other:?}; expected paths or resolved"),
  99	    }
 100	}
