 302	/// Whether `text` uses `word` as a whole identifier. `contains` would match a
 303	/// one-letter alias inside every other identifier in the file.
 304	fn mentions_word(text: &str, word: &str) -> bool {
 305	    text.match_indices(word).any(|(at, _)| {
 306	        let before = text[..at].chars().next_back();
 307	        let after = text[at + word.len()..].chars().next();
 308	        let boundary = |ch: Option<char>| !ch.is_some_and(|c| c.is_alphanumeric() || c == '_');
 309	        boundary(before) && boundary(after)
 310	    })
 311	}
