 809	/// Verify completed HAQP qualification evidence. Planned or NOT_RUN packet rows
 810	/// fail here; this is the command used by the M17 packet gate.
 811	pub fn verify_qualified_repo(root: &Utf8Path) -> Result<()> {
 812	    let packet = read_packet(root)?;
 813	    verify_packet_shape(&packet)?;
 814	    verify_requirement_sources(root, &packet)?;
 815	    verify_crash_boundary_scope(root, &packet)?;
 816	    verify_markdown_surface(root, &packet)?;
 817	    // Blind pass 1 at 5fb1b57 (A09): both of these ran on the inventory path
 818	    // only, so the path that judges a FLIPPED packet — the one that matters —
 819	    // accepted review cells disagreeing with their records and an oracle
 820	    // coupled to the production path it judges.
 821	    verify_markdown_review_blocks(root, &packet)?;
 822	    verify_markdown_tables(root, &packet)?;
 823	    verify_oracle_independence(root)?;
 824	    require_eq(
 825	        "qualification_state",
 826	        &packet.qualification_state,
 827	        "complete",
 828	    )?;
 829	    verify_mutant_source_coordinates(root, &packet)?;
 830	    verify_packet_statuses(
 831	        &packet,
 832	        PacketStatusExpectations {
 833	            // ADR-0021 stages the mutation requirement, so the expected mutant
 834	            // disposition is stage-dependent. Hardcoding `killed` here made
 835	            // HAQP-1a UNREACHABLE: leave mutants `predeclared` and this gate
 836	            // failed; mark one `killed` and verify_qualification_stage failed.
 837	            // The first version of ADR-0021 shipped with exactly that
 838	            // contradiction — the deadlock it existed to break, reintroduced
 839	            // one layer down.
 840	            mutant: if packet.qualification_stage == "1b" {
 841	                "resolved"
 842	            } else {
 843	                "predeclared"
 844	            },
 845	            canary: "caught",
 846	            generated: "pass",
 847	            crash: "pass",
 848	            review: "pass",
 849	        },
 850	    )?;
 851	    // M17.5 A6 / pass-2 #14,#15,#17,#19,#21: statuses are CLAIMS. Bind them to
 852	    // artifacts a run actually produced, or the whole gate is satisfiable by
 853	    // editing two files.
 854	    verify_provenance(root, &packet)?;
 855	    verify_concurrency_evidence(root, &packet)?;
 856	    verify_fuzz_evidence(root, &packet)?;
 857	    verify_locked_corpus_has_no_aliases(root)?;
 858	    verify_corpus_access_audit(root, &packet)?;
 859	    verify_crash_evidence(root, &packet)?;
 860	    verify_crash_replay(root, &packet)?;
 861	    let provenance = packet
 862	        .provenance
 863	        .as_ref()
 864	        .context("qualified campaign clock requires packet provenance")?;
 865	    verify_campaign_clock(root, &packet, Some(provenance))?;
 866	    verify_residual_risks(root, &packet)?;
 867	    verify_qualification_stage(&packet)?;
 868	    if packet.qualification_stage == "1b" {
 869	        // M17.5 F-33: 36 of the 65 declared mutants are anchored to
 870	        // declarations and cannot be applied. ADR-0021 defers §3's mutation
 871	        // clauses to 1b, so this refuses there rather than blocking 1a on work
 872	        // that milestone already deferred — but it MUST refuse, or M24
 873	        // rediscovers it after Phase 1 is built.
 874	        verify_mutant_anchors_support_operators(root, &packet)?;
 875	        verify_mutant_killing_tests(root, &packet)?;
 876	        verify_mutant_evidence(root, &packet)?;
 877	        verify_mutant_evidence_replay(root, &packet)?;
 878	    }
 879	    verify_canary_evidence(root, &packet)?;
 880	    verify_generated_evidence(root, &packet)?;
