2509	/// A reviewer cannot make its own "independent reproduction" true by setting
2510	/// two booleans in one record. Every reproduced finding must have one matching
2511	/// verified defect in the other isolated pass, with the same attack class,
2512	/// exact source target, and identical falsification claim/observation. This
2513	/// prevents two semantically different reports at one line from becoming a
2514	/// concurrence by coordinate coincidence; finding IDs remain pass-local.
2515	/// Whether two blinded passes are reporting the same defect. Blind pass 1 at
2516	/// `0a0b4b4b` (A10): this required the `attempt` and `observed_result` strings
2517	/// to be byte-identical. Two reviewers who cannot see each other's work will
2518	/// not write the same sentence, so a genuine independent reproduction was
2519	/// rejected unless they coordinated wording — which is the one thing the
2520	/// blinding exists to prevent. The class and the coordinate already match by
2521	/// the time this is asked; what is left to establish is that the two are about
2522	/// the same thing, and shared vocabulary establishes it. Four significant
2523	/// words in common is far more than coincidence at one coordinate and far less
2524	/// than dictation.
2525	fn reports_the_same_defect(left: &ReviewRecordAttempt, right: &ReviewRecordAttempt) -> bool {
2526	    // Blind pass 1 at `ec045588` (A02): both reports name the coordinate, so
2527	    // `crates`, `liminal`, `xtask` and `haq` were four shared words before
2528	    // either said anything — the coordinate matched twice, once as itself and
2529	    // once as vocabulary. Words the coordinate already carries are struck out,
2530	    // and so are the handful this campaign puts in every report.
2531	    const UBIQUITOUS: [&str; 8] = [
2532	        "verifier",
2533	        "verify",
2534	        "packet",
2535	        "evidence",
2536	        "check",
2537	        "checks",
2538	        "because",
2539	        "committed",
2540	    ];
2541	    let coordinate: BTreeSet<String> = format!("{} {}", left.target, right.target)
2542	        .to_ascii_lowercase()
2543	        .split(|ch: char| !ch.is_alphanumeric() && ch != '_')
2544	        .map(str::to_owned)
2545	        .collect();
2546	    let vocabulary = |attempt: &ReviewRecordAttempt| {
2547	        format!("{} {}", attempt.attempt, attempt.observed_result)
2548	            .to_ascii_lowercase()
2549	            .split(|ch: char| !ch.is_alphanumeric() && ch != '_')
2550	            .filter(|word| word.len() >= 4)
2551	            .filter(|word| !coordinate.contains(*word))
2552	            .filter(|word| !UBIQUITOUS.contains(word))
2553	            .map(str::to_owned)
2554	            .collect::<BTreeSet<_>>()
2555	    };
2556	    vocabulary(left).intersection(&vocabulary(right)).count() >= 4
2557	}
