2750	/// The findings a record leaves unresolved after standing rulings: verified,
2751	/// independently reproduced, not resolved by a fix proof, and not covered by
2752	/// a ruling in force on the same attack class and target file. Read as plain
2753	/// JSON so the count is over what was persisted.
2754	pub fn effective_unresolved_findings_repo(root: &Utf8Path, record: &Utf8Path) -> Result<u64> {
2755	    let value: serde_json::Value =
2756	        serde_json::from_slice(&fs::read(record)?).with_context(|| format!("parse {record}"))?;
2757	    let in_force = rulings(root)?
2758	        .into_iter()
2759	        .filter(|ruling| ruling_in_force(root, ruling).unwrap_or(false))
2760	        .collect::<Vec<_>>();
2761	    effective_unresolved_findings(&in_force, &value, record)
