8521	fn authoritative_requirement_map()
8522	-> BTreeMap<&'static str, (&'static str, &'static str, bool, bool)> {
8523	    AUTHORITATIVE_REQUIREMENTS
8524	        .iter()
8525	        .map(|(id, kind, source, critical, stateful)| (*id, (*kind, *source, *critical, *stateful)))
8526	        .collect()
