 178	/// Every definition of `name` in `text`. All of them, not the first: a crate's
 179	/// modules concatenate here, and two modules may name a function alike.
 180	fn item_bodies<'a>(text: &'a str, name: &str) -> Vec<&'a str> {
 181	    // Blind pass 1 at `0a0b4b4b` (A02): a macro is an item the oracle can
 182	    // reach, and its body is where the production call would sit — following
 183	    // functions alone left `production!()` outside the scanned body.
 184	    let needles = [format!("fn {name}("), format!("macro_rules! {name}")];
 185	    let mut out = Vec::new();
 186	    for needle in &needles {
 187	        let mut from = 0;
 188	        while let Some(offset) = text[from..].find(needle.as_str()) {
 189	            let start = from + offset;
 190	            let rest = &text[start..];
 191	            let end = rest.find("\n}\n").map_or(rest.len(), |index| index + 2);
 192	            out.push(&rest[..end]);
 193	            from = start + needle.len();
 194	        }
 195	    }
 196	    out
 197	}
