2629	/// The record's digests: hex-shaped, and the raw one the SHA-256 of the
2630	/// retained answer (A09: a digest of nothing retained bound a record to no
2631	/// answer).
2632	/// A standing ruling on a class of reviewer finding (grilling decision 6,
2633	/// 2026-09-03): a finding Brian rules incorrect is cleared by a ruling
2634	/// commit signed against the pinned signer, never by editing the record.
2635	/// Rulings live in `docs/execution/rulings/*.md` with a front matter of
2636	/// `id`, `attack_class`, `target` (a repository path) and `status`
2637	/// (`draft` or `ruled`). A ruling cannot name its own commit, so the commit
2638	/// that counts is the last one that touched the ruling's file.
2639	#[derive(Debug, Clone, PartialEq, Eq)]
2640	struct Ruling {
2641	    id: String,
2642	    attack_class: String,
2643	    target: String,
2644	    /// Phrases that must all appear in an attempt's prose for this ruling to
2645	    /// answer it. Blind pass 1 at aa00d41 (A08): matching on class and file
2646	    /// alone cleared an unrelated second claim in the same class and file —
2647	    /// R-001, written for "stage reads are leakage", silently cleared a
2648	    /// genuine untracked-chdir defect. A ruling answers a claim, not a
2649	    /// coordinate.
2650	    claim_requires: Vec<String>,
2651	    /// Phrases whose presence means this ruling does NOT answer the claim.
2652	    /// Blind pass 1 at 5fb1b57 (A08): a required phrase can be found inside a
2653	    /// sentence that negates it, so a ruling could suppress a defect it was
2654	    /// never shown. Required phrases say what a claim must be about;
2655	    /// excluded ones say what it must not be about.
2656	    claim_excludes: Vec<String>,
2657	    status: String,
2658	    file: String,
2659	}
2660	
2661	const RULING_SIGNERS: &str = "conformance/haqp/ruling-signers";
2662	
2663	fn rulings(root: &Utf8Path) -> Result<Vec<Ruling>> {
2664	    let dir = root.join("docs/execution/rulings");
2665	    if !dir.is_dir() {
2666	        return Ok(Vec::new());
2667	    }
2668	    let mut files = fs::read_dir(dir.as_std_path())?
2669	        .map(|entry| entry.map(|e| e.path()))
2670	        .collect::<std::io::Result<Vec<_>>>()?;
2671	    files.sort();
2672	    let mut out = Vec::new();
2673	    for file in files {
2674	        let file = Utf8PathBuf::from_path_buf(file)
2675	            .map_err(|p| anyhow::anyhow!("non-UTF-8 path {}", p.display()))?;
2676	        if file.extension() != Some("md") {
2677	            continue;
2678	        }
2679	        let text = fs::read_to_string(&file)?;
2680	        let front = text
2681	            .strip_prefix("---\n")
2682	            .and_then(|rest| rest.split_once("\n---\n"))
2683	            .map(|(front, _)| front)
2684	            .with_context(|| format!("{file}: ruling has no front matter"))?;
2685	        let field = |key: &str| -> Result<String> {
2686	            front
2687	                .lines()
2688	                .find_map(|line| line.strip_prefix(&format!("{key}: ")))
2689	                .map(|v| v.trim().trim_matches('"').to_owned())
2690	                .with_context(|| format!("{file}: ruling front matter lacks {key}"))
2691	        };
2692	        let excludes = field("claim_excludes").unwrap_or_default();
2693	        let requires = field("claim_requires")?;
2694	        anyhow::ensure!(
2695	            !requires.trim().is_empty(),
2696	            "{file}: ruling claim_requires is empty; a ruling that answers any claim in its \
2697	             class and file clears defects it was never shown (A08)"
2698	        );
2699	        out.push(Ruling {
2700	            id: field("id")?,
2701	            attack_class: field("attack_class")?,
2702	            target: field("target")?,
2703	            claim_requires: requires
2704	                .split(';')
2705	                .map(|phrase| phrase.trim().to_ascii_lowercase())
2706	                .filter(|phrase| !phrase.is_empty())
2707	                .collect(),
2708	            claim_excludes: excludes
2709	                .split(';')
2710	                .map(|phrase| phrase.trim().to_ascii_lowercase())
2711	                .filter(|phrase| !phrase.is_empty())
2712	                .collect(),
2713	            status: field("status")?,
2714	            file: file.strip_prefix(root).unwrap_or(&file).to_string(),
2715	        });
2716	    }
2717	    Ok(out)
2718	}
