3210	fn verify_review_attack_classes(record: &ReviewRecord, who: &str) -> Result<()> {
3211	    let mut seen = BTreeSet::new();
3212	    for attempt in &record.attempts {
3213	        anyhow::ensure!(
3214	            REVIEW_ATTACK_CLASSES.contains(&attempt.attack_class.as_str()),
3215	            "{who}: attempt {} uses unknown attack class {:?}",
3216	            attempt.id,
3217	            attempt.attack_class
3218	        );
3219	        seen.insert(attempt.attack_class.as_str());
3220	    }
3221	    if record.pass == 1 {
3222	        let missing = REVIEW_ATTACK_CLASSES
3223	            .iter()
3224	            .filter(|class| !seen.contains(**class))
3225	            .copied()
3226	            .collect::<Vec<_>>();
3227	        anyhow::ensure!(
3228	            missing.is_empty(),
3229	            "{who}: Pass 1 is missing attack classes {missing:?}"
3230	        );
