3235	fn verify_review_findings(
3236	    review: &Review,
3237	    record: &ReviewRecord,
3238	    who: &str,
3239	    root: &Utf8Path,
3240	) -> Result<()> {
3241	    require_hex_digest(
3242	        "review isolated_session_hash",
3243	        &record.isolated_session_hash,
3244	    )?;
3245	    let record_findings = review_finding_ids(&record.findings, &record.attempts, who)?;
3246	    let packet_findings = review
3247	        .findings
3248	        .iter()
3249	        .map(String::as_str)
3250	        .collect::<BTreeSet<_>>();
3251	    if record_findings.len() != review.findings.len() {
3252	        anyhow::bail!(
3253	            "{who} lists {} findings but its record contains {}",
3254	            review.findings.len(),
3255	            record.findings.len()
3256	        );
3257	    }
3258	    if record_findings.keys().copied().collect::<BTreeSet<_>>() != packet_findings {
3259	        anyhow::bail!("{who} packet findings do not match its committed record");
3260	    }
3261	    let mut reproduced = BTreeSet::new();
3262	    for finding_id in &record.independently_reproduced {
3263	        anyhow::ensure!(
3264	            reproduced.insert(finding_id.as_str()),
3265	            "{who}: independently reproduced finding id {finding_id:?} appears twice"
3266	        );
3267	        anyhow::ensure!(
3268	            record_findings.contains_key(finding_id.as_str()),
3269	            "{who}: independently reproduced finding {finding_id:?} is absent from record"
3270	        );
3271	        let attempt_id = record_findings[finding_id.as_str()];
3272	        let attempt = record
3273	            .attempts
