8428	    // The inventory grows as evidence kinds are declared (M17.5 F-05): the IDs
8429	    // must stay dense and sequential, but the COUNT is not frozen at 8 — that
8430	    // ceiling was the mechanism that kept 36 requirements on 8 coarse tests.
8431	    require_exact_ids(
8432	        packet.tests.iter().map(|row| row.id.as_str()),
8433	        (1..=packet.tests.len()).map(|idx| format!("P1-T{idx:02}")),
8434	        "test",
8435	    )?;
