  8529	/// Evidence kinds every applicable critical requirement must carry
  8530	/// (ADR-0020 §2: "positive, negative, malformed/adversarial, basis/provenance,
  8531	/// and deterministic-replay evidence").
  8532	const CORE_EVIDENCE: [&str; 5] = ["positive", "negative", "malformed", "basis", "replay"];
  8533	/// "Stateful laws also have injected-fault and idempotent-recovery evidence."
  8534	const STATEFUL_EVIDENCE: [&str; 2] = ["fault", "recovery"];
  8535	/// Requirement kinds are closed by the HAQP packet contract. An open kind
  8536	/// vocabulary lets a packet relabel a stateful requirement and evade its
  8537	/// fault/recovery evidence obligations (M17.5 P1-A04).
  8538	const REQUIREMENT_KINDS: [&str; 4] = ["law", "gate", "fault", "abuse"];
  8539	/// Current packet's stateful law is M20 D20.3. Keep the semantic coordinate
  8540	/// closed even if an attacker relabels its `kind` or drops its JSON marker.
  8541	const STATEFUL_REQUIREMENT_IDS: [&str; 1] = ["P1-R015"];
  8542	/// No single test may carry more than this share of the mutation denominator.
  8543	const MAX_KILL_SHARE: f64 = 0.25;
  8544	
  8545	/// M17.5 F-05: a requirement mapped to one coarse end-to-end test is not
  8546	/// covered. Every critical requirement must carry all five core evidence
  8547	/// kinds, and fault-class requirements must additionally carry injected-fault
  8548	/// and idempotent-recovery evidence.
  8549	fn verify_evidence_coverage(packet: &Packet) -> Result<()> {
  8550	    let known = CORE_EVIDENCE
  8551	        .iter()
  8552	        .chain(STATEFUL_EVIDENCE.iter())
  8553	        .copied()
  8554	        .collect::<BTreeSet<_>>();
  8555	    let mut covered = BTreeMap::<&str, BTreeSet<&str>>::new();
  8556	    for test in &packet.tests {
  8557	        if test.evidence.is_empty() {
  8558	            anyhow::bail!("{} declares no evidence kind", test.id);
  8559	        }
  8560	        for kind in &test.evidence {
  8561	            if !known.contains(kind.as_str()) {
  8562	                anyhow::bail!("{} declares unknown evidence kind {kind}", test.id);
  8563	            }
  8564	        }
  8565	        for requirement in &test.requirements {
  8566	            covered
  8567	                .entry(requirement.as_str())
  8568	                .or_default()
  8569	                .extend(test.evidence.iter().map(String::as_str));
  8570	        }
  8571	    }
  8572	    for requirement in &packet.requirements {
  8573	        if !requirement.critical {
  8574	            continue;
  8575	        }
  8576	        let have = covered
  8577	            .get(requirement.id.as_str())
  8578	            .cloned()
  8579	            .unwrap_or_default();
  8580	        let mut needed = CORE_EVIDENCE.to_vec();
  8581	        if requirement.stateful || requirement.kind == "fault" {
  8582	            needed.extend_from_slice(&STATEFUL_EVIDENCE);
  8583	        }
  8584	        let missing = needed
  8585	            .into_iter()
  8586	            .filter(|kind| !have.contains(kind))
  8587	            .collect::<Vec<_>>();
  8588	        if !missing.is_empty() {
  8589	            anyhow::bail!(
  8590	                "critical requirement {} ({}) is missing {} evidence",
  8591	                requirement.id,
  8592	                requirement.kind,
  8593	                missing.join(", ")
  8594	            );
  8595	        }
  8596	    }
  8597	    Ok(())
  8598	}
