  8600	/// Closed digest over test identity, executable name, requirement mapping, and
  8601	/// evidence kinds. Existence checks alone let a packet remap broad, unrelated
  8602	/// test names to satisfy coverage; this registry makes the authoritative
  8603	/// mapping tamper-evident (P1-A04). Recompute with the canonical NUL/US stream
  8604	/// below and update this constant in the same commit as any test inventory edit.
  8605	const TEST_REGISTRY_SHA256: &str =
  8606	    "7a29add0e81657e17786934010638abf1ea99dfee4e162921a9ef2699197d447";
  8607	
  8608	fn verify_test_registry(packet: &Packet) -> Result<()> {
  8609	    let mut canonical = String::new();
  8610	    for test in &packet.tests {
  8611	        canonical.push_str(&test.id);
  8612	        canonical.push('\0');
  8613	        canonical.push_str(&test.name);
  8614	        canonical.push('\0');
  8615	        canonical.push_str(&test.requirements.join("\x1f"));
  8616	        canonical.push('\0');
  8617	        canonical.push_str(&test.evidence.join("\x1f"));
  8618	        canonical.push('\0');
  8619	    }
  8620	    let digest = sha256_text(&canonical);
  8621	    anyhow::ensure!(
  8622	        digest == TEST_REGISTRY_SHA256,
  8623	        "test registry digest differs from closed authority: got {digest}, expected {TEST_REGISTRY_SHA256}"
  8624	    );
  8625	    Ok(())
  8626	}
