  8628	fn contains_exact_coordinate(text: &str, coordinate: &str) -> bool {
  8629	    text.match_indices(coordinate).any(|(start, _)| {
  8630	        let end = start + coordinate.len();
  8631	        !text[..start]
  8632	            .chars()
  8633	            .next_back()
  8634	            .is_some_and(|ch| ch.is_ascii_alphanumeric() || ch == ':')
  8635	            && !text[end..]
  8636	                .chars()
  8637	                .next()
  8638	                .is_some_and(|ch| ch.is_ascii_alphanumeric() || ch == ':')
  8639	    })
  8640	}
