  8642	/// M17.5 F-05: ADR-0020 §3 forbids mutation coverage clustering on
  8643	/// easy-to-kill paths. A 100% kill rate carried by a handful of coarse
  8644	/// end-to-end tests measures almost nothing, so cap any one test's share of
  8645	/// the denominator and require every named killer to exist.
  8646	fn verify_kill_concentration(packet: &Packet) -> Result<()> {
  8647	    let total = packet.mutants.len();
  8648	    if total == 0 {
  8649	        return Ok(());
  8650	    }
  8651	    let test_ids = packet
  8652	        .tests
  8653	        .iter()
  8654	        .map(|row| row.id.as_str())
  8655	        .collect::<BTreeSet<_>>();
  8656	    let mut kills = BTreeMap::<&str, usize>::new();
  8657	    for mutant in &packet.mutants {
  8658	        for test in &mutant.killing_tests {
  8659	            if !test_ids.contains(test.as_str()) {
  8660	                anyhow::bail!("{} names unknown killing test {test}", mutant.id);
  8661	            }
  8662	            *kills.entry(test.as_str()).or_default() += 1;
  8663	        }
  8664	    }
  8665	    for (test, count) in &kills {
  8666	        #[allow(clippy::cast_precision_loss, reason = "inventory-scale counts")]
  8667	        let share = *count as f64 / total as f64;
  8668	        // M17.5 F-30: `>` -> `>=` survives here and is EQUIVALENT within the
  8669	        // reachable domain. `share` is `count / total` over 65 declared
  8670	        // mutants, and 65/4 is not an integer, so `share == 0.25` exactly
  8671	        // cannot occur.
  8672	        if share > MAX_KILL_SHARE {
  8673	            anyhow::bail!(
  8674	                "{test} is the named killer for {count}/{total} mutants ({:.0}%), \
  8675	                 above the {:.0}% ceiling — mutation coverage is clustering on one \
  8676	                 coarse test",
  8677	                share * 100.0,
  8678	                MAX_KILL_SHARE * 100.0
  8679	            );
  8680	        }
  8681	    }
  8682	    Ok(())
  8683	}
