  6731	/// Two-path syscalls yield both strings; a symlink's target counts as written
  6732	/// because a link INTO the locked corpus is the second-name attack. strace
  6733	/// prints one syscall per line, so the earliest needle is the line's call.
  6734	fn scope_trace_line_accesses(line: &str) -> Vec<(String, bool)> {
  6735	    scope_trace_line_arguments(line)
  6736	        .into_iter()
  6737	        .map(|(path, write, _)| (path, write))
  6738	        .collect()
  6739	}
  6740	
  6741	/// The same, plus the directory fd each path was resolved against: the nearest
  6742	/// preceding bare integer argument, `None` for `AT_FDCWD` and for calls that
  6743	/// take no dirfd. Blind pass 1 at 5fb1b57 (A10, A11): only `openat`'s FIRST
  6744	/// argument was read, so `renameat`'s destination dirfd was ignored and a
  6745	/// descriptor opened without `O_DIRECTORY` was dropped from the map entirely.
  6746	fn scope_trace_line_arguments(line: &str) -> Vec<(String, bool, Option<i64>)> {
  6747	    let Some((open, needle)) = FILE_SYSCALLS
  6748	        .into_iter()
  6749	        .filter_map(|needle| line.find(needle).map(|index| (index, needle)))
  6750	        .min_by_key(|(index, _)| *index)
  6751	    else {
  6752	        return Vec::new();
  6753	    };
  6754	    let rest = &line[open..];
  6755	    let write = WRITE_SYSCALLS.contains(&needle)
  6756	        || (OPEN_SYSCALLS.contains(&needle)
  6757	            && OPEN_WRITE_FLAGS.iter().any(|flag| rest.contains(flag)));
  6758	    let wanted = if TWO_PATH_SYSCALLS.contains(&needle) {
  6759	        2
  6760	    } else {
  6761	        1
  6762	    };
  6763	    let mut out = Vec::with_capacity(wanted);
  6764	    // The argument list, past the syscall name: without this the text before a
  6765	    // path reads `openat(7`, whose last comma-separated piece is the name
  6766	    // glued to the fd and parses as nothing.
  6767	    let args = &rest[needle.len()..];
  6768	    let mut cursor = args;
  6769	    let mut consumed = 0usize;
  6770	    for _ in 0..wanted {
  6771	        let Some(start) = cursor.find('"') else { break };
  6772	        let Some(end) = cursor[start + 1..].find('"') else {
  6773	            break;
  6774	        };
  6775	        let dirfd = args[..consumed + start]
  6776	            .rsplit(',')
  6777	            .find_map(|argument| argument.trim().parse::<i64>().ok());
  6778	        out.push((cursor[start + 1..start + 1 + end].to_owned(), write, dirfd));
  6779	        consumed += start + 1 + end + 1;
  6780	        cursor = &cursor[start + 1 + end + 1..];
  6781	    }
  6782	    out
  6783	}
