  7431	            "{label}: relative fuzz corpus path lacks authenticated cwd/dirfd binding"
  7432	        ),
  7433	        LockedCorpus::AnyTouch => Ok(false),
  7434	        LockedCorpus::WritesOnly => Ok(true),
  7435	    }
  7436	}
