  7501	/// Canonicalize the existing prefix of a traced path, then append historical
  7502	/// leaf components that libFuzzer may have deleted after opening them. This
  7503	/// preserves symlink and root-boundary checks without requiring every path in
  7504	/// a long-running trace to remain present at receipt time.
  7505	fn canonicalize_trace_path(path: &Path) -> Result<std::path::PathBuf> {
  7506	    let mut missing = Vec::new();
  7507	    let mut cursor = path;
  7508	    loop {
  7509	        match fs::symlink_metadata(cursor) {
  7510	            Ok(_) => break,
  7511	            Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
  7512	                missing.push(
  7513	                    cursor
  7514	                        .file_name()
  7515	                        .context("traced path has no recoverable leaf")?
  7516	                        .to_owned(),
  7517	                );
  7518	                let leaf = missing.last().expect("just pushed missing leaf");
  7519	                anyhow::ensure!(
  7520	                    leaf != std::ffi::OsStr::new(".") && leaf != std::ffi::OsStr::new(".."),
  7521	                    "traced path contains a parent-directory suffix"
  7522	                );
  7523	                cursor = cursor
  7524	                    .parent()
  7525	                    .context("traced path has no existing ancestor")?;
  7526	                anyhow::ensure!(
  7527	                    cursor.file_name() != Some(std::ffi::OsStr::new("corpus")),
  7528	                    "traced path is missing a corpus entry; symlink history is unavailable"
  7529	                );
  7530	            }
  7531	            Err(error) => return Err(error.into()),
  7532	        }
  7533	    }
  7534	    let mut canonical = fs::canonicalize(cursor)?;
  7535	    for component in missing.into_iter().rev() {
  7536	        canonical.push(component);
  7537	    }
