10503	            );
10504	        }
10505	        let mut family_minutes = 0_u64;
10506	        for target in &family.fuzz_targets {
10507	            let recorded_seconds = elapsed_seconds.get(target.as_str()).with_context(|| {
10508	                format!(
10509	                    "{} names fuzz target {target:?}, which the committed campaign did not run",
10510	                    family.family
