 2720	/// A ruling is in force when its status is `ruled` and the last commit that
 2721	/// touched its file verifies against the pinned signers. A draft, an
 2722	/// uncommitted edit, or an unsigned commit clears nothing.
 2723	fn ruling_in_force(root: &Utf8Path, ruling: &Ruling) -> Result<bool> {
 2724	    if ruling.status != "ruled" {
 2725	        return Ok(false);
 2726	    }
 2727	    let signers = root.join(RULING_SIGNERS);
 2728	    anyhow::ensure!(
 2729	        signers.is_file(),
 2730	        "{RULING_SIGNERS} is missing; a ruling cannot be verified against no signer"
 2731	    );
 2732	    let dirty = git_text(root, &["status", "--porcelain", "--", &ruling.file])?;
 2733	    if !dirty.trim().is_empty() {
 2734	        return Ok(false);
 2735	    }
 2736	    let commit = git_text(root, &["log", "-1", "--format=%H", "--", &ruling.file])?;
 2737	    if commit.trim().is_empty() {
 2738	        return Ok(false);
 2739	    }
 2740	    let verified = Command::new("git")
 2741	        .current_dir(root)
 2742	        .args(["-c", "gpg.format=ssh", "-c"])
 2743	        .arg(format!("gpg.ssh.allowedSignersFile={signers}"))
 2744	        .args(["verify-commit", commit.trim()])
 2745	        .output()
 2746	        .context("git verify-commit")?;
 2747	    Ok(verified.status.success())
 2748	}
