 2764	/// The count, given the rulings already established to be in force. Split from
 2765	/// the repository walk so the clearance rules can be exercised without a
 2766	/// signing key: a rule the tests cannot reach is a rule nothing checks.
 2767	fn effective_unresolved_findings(
 2768	    in_force: &[Ruling],
 2769	    value: &serde_json::Value,
 2770	    record: &Utf8Path,
 2771	) -> Result<u64> {
 2772	    // Counted from each attempt's own flags, not through the findings list:
 2773	    // a verified, reproduced attempt the reviewer forgot to list as a finding
 2774	    // is still unresolved.
 2775	    let mut unresolved = 0u64;
 2776	    let mut cleared: BTreeMap<String, u64> = BTreeMap::new();
 2777	    for attempt in value["attempts"].as_array().into_iter().flatten() {
 2778	        let class = attempt["attack_class"].as_str().unwrap_or_default();
 2779	        let target = attempt["target"].as_str().unwrap_or_default();
 2780	        if attempt["classification"].as_str() != Some("verified_defect")
 2781	            || !attempt["independently_reproduced"]
 2782	                .as_bool()
 2783	                .unwrap_or(false)
 2784	            || attempt["resolved"].as_bool().unwrap_or(false)
 2785	        {
 2786	            continue;
 2787	        }
 2788	        let target_file = target.split(':').next().unwrap_or(target);
 2789	        let prose = format!(
 2790	            "{} {}",
 2791	            attempt["attempt"].as_str().unwrap_or_default(),
 2792	            attempt["observed_result"].as_str().unwrap_or_default()
 2793	        )
 2794	        .to_ascii_lowercase();
 2795	        // Blind pass 1 at c29bc0ea (A08): a ruling matched on class, file and
 2796	        // prose substrings, so an unrelated defect in the same file whose
 2797	        // wording happened to carry the required phrases was cleared in
 2798	        // silence. Two things changed. A ruling that names a coordinate is
 2799	        // held to it, not merely to the file. And a ruling clears at most one
 2800	        // attempt per record: matching a second is evidence the phrases are
 2801	        // too broad, and the answer to that is a refusal, not two clearances.
 2802	        let matched = in_force
 2803	            .iter()
 2804	            .filter(|ruling| {
 2805	                ruling.attack_class == class
 2806	                    && if ruling.target.contains(':') {
 2807	                        ruling.target == target
 2808	                    } else {
 2809	                        ruling.target == target_file
 2810	                    }
 2811	                    && ruling
 2812	                        .claim_requires
 2813	                        .iter()
 2814	                        .all(|phrase| prose.contains(phrase.as_str()))
 2815	                    && !ruling
 2816	                        .claim_excludes
 2817	                        .iter()
 2818	                        .any(|phrase| prose.contains(phrase.as_str()))
 2819	            })
 2820	            .collect::<Vec<_>>();
 2821	        for ruling in &matched {
 2822	            *cleared.entry(ruling.id.clone()).or_insert(0u64) += 1;
 2823	        }
 2824	        if matched.is_empty() {
 2825	            unresolved += 1;
 2826	        }
 2827	    }
 2828	    for (id, count) in &cleared {
 2829	        anyhow::ensure!(
 2830	            *count <= 1,
 2831	            "ruling {id} cleared {count} separate findings in {record}; a ruling \
 2832	                 answers one claim, so phrases matching more than one are too \
 2833	                 broad to stand"
 2834	        );
 2835	    }
 2836	    Ok(unresolved)
 2837	}
