  2839	/// The receipt must be the backend's own shape, and a Codex transcript must be
  2840	/// retained beside the record and hash to what the receipt claims (F-49).
  2841	fn verify_review_provider_receipt(record: &ReviewRecord, record_path: &Utf8Path) -> Result<()> {
  2842	    let receipt = &record.provider_receipt;
  2843	    require_eq(
  2844	        "review provider_receipt backend",
  2845	        &receipt.backend,
  2846	        &record.reviewer.backend,
  2847	    )?;
  2848	    match receipt.backend.as_str() {
  2849	        "codex" => {
  2850	            anyhow::ensure!(
  2851	                !receipt.session_id.trim().is_empty() && !receipt.session_file.trim().is_empty(),
  2852	                "a codex receipt must name the session that answered"
  2853	            );
  2854	            require_hex_digest("review transcript_sha256", &receipt.transcript_sha256)?;
  2855	            let transcript = record_path.with_extension("session.jsonl");
  2856	            let bytes = fs::read(&transcript).with_context(|| {
  2857	                format!("{transcript}: the codex transcript must be retained beside its record")
  2858	            })?;
  2859	            anyhow::ensure!(
  2860	                bytes.len() as u64 == receipt.transcript_bytes,
  2861	                "codex transcript is {} bytes, receipt claims {}",
  2862	                bytes.len(),
  2863	                receipt.transcript_bytes
  2864	            );
  2865	            require_eq(
  2866	                "review transcript_sha256 (of the retained transcript)",
  2867	                &format!("{:x}", Sha256::digest(&bytes)),
  2868	                &receipt.transcript_sha256,
  2869	            )?;
  2870	            // Blind pass 1 at `aeed70f9` (A09): the transcript's bytes were
  2871	            // authenticated and its IDENTITY was not — `session_id` and
  2872	            // `session_file` only had to be non-empty, so a record could name
  2873	            // one session and retain another's rollout. A rollout opens with
  2874	            // its own `session_meta`, and the receipt's id ends with the UUID
  2875	            // that record carries.
  2876	            let first = std::str::from_utf8(&bytes)
  2877	                .context("codex transcript is not UTF-8")?
  2878	                .lines()
  2879	                .next()
  2880	                .context("codex transcript is empty")?;
  2881	            let meta: serde_json::Value = serde_json::from_str(first)
  2882	                .context("codex transcript's first record is not JSON")?;
  2883	            anyhow::ensure!(
  2884	                meta["type"] == "session_meta",
  2885	                "a codex rollout opens with session_meta; this one opens with {:?}",
  2886	                meta["type"]
  2887	            );
  2888	            let declared = meta["payload"]["session_id"]
  2889	                .as_str()
  2890	                .context("codex session_meta carries no session_id")?;
  2891	            // Codex names a rollout `<timestamp>-<uuid>` and its `session_meta`
  2892	            // carries the bare uuid, so the receipt's id either IS the declared
  2893	            // id or ends with it after a separator. Review of `bba803d4`: a
  2894	            // bare `ends_with` would also accept `xfixture` for `fixture`,
  2895	            // which is a different session.
  2896	            anyhow::ensure!(
  2897	                receipt.session_id == declared
  2898	                    || receipt.session_id.ends_with(&format!("-{declared}")),
  2899	                "receipt names session {:?}, retained transcript is session {declared:?}",
  2900	                receipt.session_id
  2901	            );
  2902	            require_eq(
  2903	                "review provider_receipt session_file",
  2904	                &receipt.session_file,
  2905	                &format!("rollout-{}.jsonl", receipt.session_id),
  2906	            )
  2907	        }
  2908	        "mimo-direct" => {
  2909	            anyhow::ensure!(
  2910	                !receipt.response_id.trim().is_empty(),
  2911	                "a mimo receipt must carry the provider's response id"
  2912	            );
  2913	            anyhow::ensure!(
  2914	                !receipt.provider_model.trim().is_empty(),
  2915	                "a mimo receipt must carry the model the provider says answered"
  2916	            );
  2917	            anyhow::ensure!(
  2918	                receipt.created > 0,
  2919	                "a mimo receipt must carry the provider's clock"
  2920	            );
  2921	            for key in ["prompt_tokens", "completion_tokens", "total_tokens"] {
  2922	                anyhow::ensure!(
  2923	                    receipt.usage.contains_key(key),
  2924	                    "a mimo receipt must carry the provider's {key}; a changed usage envelope \
  2925	                     must be seen here, not discovered later through a binding that moved"
  2926	                );
  2927	            }
  2928	            let billed = receipt
  2929	                .usage
  2930	                .get("total_tokens")
  2931	                .and_then(serde_json::Value::as_u64)
  2932	                .unwrap_or(0);
  2933	            anyhow::ensure!(
  2934	                billed > 0,
  2935	                "a mimo receipt must carry billed usage; {:?} bills nothing",
  2936	                receipt.usage
  2937	            );
  2938	            Ok(())
  2939	        }
  2940	        other => anyhow::bail!(
  2941	            "review backend {other:?} produced no provider receipt; ADR-0020 §6 independence \
  2942	             rests on evidence from outside this runner (F-49)"
  2943	        ),
  2944	    }
  2945	}
