 10482	/// Derive each family's fuzz minutes from the committed campaign and enforce
 10483	/// ADR-0020 §4's floors against the DERIVED value (M17.5 F-17).
 10484	///
 10485	/// The packet says which targets belong to each family; the artifact supplies
 10486	/// their seconds. Summing those rows is the sole family-budget calculation.
 10487	fn verify_fuzz_budget(declared: &[Generated], recorded: &[FuzzEvidence]) -> Result<()> {
 10488	    let elapsed_seconds: BTreeMap<&str, u64> = recorded
 10489	        .iter()
 10490	        .map(|row| (row.target.as_str(), row.elapsed_s))
 10491	        .collect();
 10492	    let mut total_minutes = 0_u64;
 10493	    for family in declared {
 10494	        if family.result != "pass" {
 10495	            continue;
 10496	        }
 10497	        if family.fuzz_targets.is_empty() {
 10498	            anyhow::bail!(
 10499	                "{} claims pass but names no fuzz target; ADR-0020 §4 gives every \
 10500	                 family its own sanitizer campaign, and a family with no target \
 10501	                 has had none",
 10502	                family.family
 10503	            );
 10504	        }
 10505	        let mut family_minutes = 0_u64;
 10506	        for target in &family.fuzz_targets {
 10507	            let recorded_seconds = elapsed_seconds.get(target.as_str()).with_context(|| {
 10508	                format!(
 10509	                    "{} names fuzz target {target:?}, which the committed campaign did not run",
 10510	                    family.family
 10511	                )
 10512	            })?;
 10513	            family_minutes += recorded_seconds / 60;
 10514	        }
 10515	        // ADR-0020 line 90: one 30-minute sanitizer campaign per family.
 10516	        if family_minutes < 30 {
 10517	            anyhow::bail!(
 10518	                "{}: its targets {:?} recorded {family_minutes} minutes, below the 30 \
 10519	                 ADR-0020 §4 requires per family",
 10520	                family.family,
 10521	                family.fuzz_targets
 10522	            );
 10523	        }
 10524	        total_minutes += family_minutes;
 10525	    }
 10526	    // ADR-0020 line 92: "Total fuzz budget is at least 150 target-minutes."
 10527	    if total_minutes < 150 {
 10528	        anyhow::bail!("derived fuzz budget {total_minutes} target-minutes is below 150");
 10529	    }
 10530	    Ok(())
 10531	}
