 5446	/// Write a target's classed seed set (A10). Deterministic, so the committed
 5447	/// seeds are reproducible from this code. It writes files only: the seeds
 5448	/// become the corpus when they are `git add -f`ed (fuzz/corpus is ignored so
 5449	/// libFuzzer's accumulation stays out) and committed, since the manifest and
 5450	/// class checks read the tracked set. `graph_interchange_codec` seeds are
 5451	/// transactions built by the same constructors the generated cases use;
 5452	/// `ilrp_recovery` seeds are the byte walks its target consumes.
 5453	pub fn write_seed_corpus_repo(root: &Utf8Path, target: &str) -> Result<()> {
 5454	    let dir = root.join("fuzz/corpus").join(target);
 5455	    fs::create_dir_all(&dir)?;
 5456	    let mut rng = Rng(0x5eed_c0de);
 5457	    let seeds: Vec<(&str, Vec<u8>)> = match target {
 5458	        "graph_interchange_codec" => {
 5459	            let txn = |rng: &mut Rng, category: &str| {
 5460	                serde_json::to_vec(&interchange_transaction(category, rng, "seed", false).0)
 5461	                    .expect("transaction encodes")
 5462	            };
 5463	            let mut boundary = interchange_transaction("single-node", &mut rng, "seed", false).0;
 5464	            boundary.parent = liminal_id::GraphRevisionId(u64::MAX);
 5465	            boundary.meta.at = liminal_id::Timestamp(i64::MAX);
 5466	            vec![
 5467	                ("01-empty.json", Vec::new()),
 5468	                ("02-single-node.json", txn(&mut rng, "single-node")),
 5469	                ("03-single-edge.json", txn(&mut rng, "single-edge")),
 5470	                ("04-dag.json", txn(&mut rng, "dag")),
 5471	                ("05-wide.json", txn(&mut rng, "wide")),
 5472	                ("06-deep.json", txn(&mut rng, "deep")),
 5473	                ("07-large-payload.json", txn(&mut rng, "large-payload")),
 5474	                ("08-duplicate-id.json", br#"{"id":"00000000-0000-0000-0000-000000000001","id":"00000000-0000-0000-0000-000000000002","parent":0,"meta":{"actor":null,"origin":"human","at":0,"provenance":null,"inverse":null},"ops":[]}"#.to_vec()),
 5475	                ("09-missing-node.json", br#"{"ops":[{"delete-node":{"id":"00000000-0000-0000-0000-000000000001"}}]}"#.to_vec()),
 5476	                ("10-unknown-kind.json", br#"{"id":"00000000-0000-0000-0000-000000000001","parent":0,"meta":{"actor":null,"origin":"nobody","at":0,"provenance":null,"inverse":null},"ops":[]}"#.to_vec()),
 5477	                ("11-comment.json", b"// not json\n{\"ops\":[]}".to_vec()),
 5478	                ("12-truncated-json.json", {
 5479	                    let mut full = txn(&mut rng, "single-edge");
 5480	                    full.truncate(full.len() / 2);
 5481	                    full
 5482	                }),
 5483	                ("13-invalid-json.bin", b"{\"ops\":[\x00\xff".to_vec()),
 5484	                ("14-boundary-revision.json", serde_json::to_vec(&boundary).expect("encodes")),
 5485	                ("15-unicode-payload.json", serde_json::to_vec(&interchange_transaction("single-node", &mut rng, "\u{1F600} \u{202e}rtl \u{0}", false).0).expect("encodes")),
 5486	                ("16-hostile.bin", vec![0, 0xff, 0x7f, b'{', b'"', 0xc3, 0x28]),
 5487	            ]
 5488	        }
 5489	        "ilrp_recovery" => {
 5490	            // Byte b drives state STATES[b % 7]: 0 Prepared, 1 Applying,
 5491	            // 2 ExternalApplied, 3 Finalizing, 4 Committed, 5 NeedsReview,
 5492	            // 6 Aborted. Legal path to Committed: 1,2,3,4.
 5493	            vec![
 5494	                ("01-empty.bin", Vec::new()),
 5495	                ("02-single-step.bin", vec![1]),
 5496	                ("03-legal-path-committed.bin", vec![1, 2, 3, 4]),
 5497	                ("04-abort-path.bin", vec![1, 6]),
 5498	                ("05-needs-review-path.bin", vec![1, 2, 5]),
 5499	                ("06-truncated-path.bin", vec![1, 2, 3]),
 5500	                ("07-boundary-max-byte.bin", vec![255, 254, 253, 252]),
 5501	                ("08-boundary-all-terminals.bin", vec![4, 5, 6, 4, 5, 6]),
 5502	                ("09-illegal-steps.bin", vec![4, 0, 3, 0, 6, 0]),
 5503	                ("10-after-terminal.bin", vec![1, 2, 3, 4, 1, 2, 3]),
 5504	                (
 5505	                    "11-long-run.bin",
 5506	                    (0..4096u32)
 5507	                        .map(|i| u8::try_from(i % 7).expect("fits"))
 5508	                        .collect(),
 5509	                ),
 5510	                (
 5511	                    "12-wide-alternating.bin",
 5512	                    (0..64u8).map(|i| if i % 2 == 0 { 1 } else { 2 }).collect(),
 5513	                ),
 5514	                (
 5515	                    "13-deep-cycle-attempt.bin",
 5516	                    vec![1, 2, 1, 2, 1, 2, 3, 2, 3, 4],
 5517	                ),
 5518	                (
 5519	                    "14-invalid-high-bytes.bin",
 5520	                    vec![0x80, 0x90, 0xa0, 0xb0, 0xc0, 0xd0, 0xe0, 0xf0],
 5521	                ),
 5522	                (
 5523	                    "15-hostile-random.bin",
 5524	                    (0..256)
 5525	                        .map(|_| u8::try_from(rng.below(256)).expect("fits"))
 5526	                        .collect(),
 5527	                ),
 5528	                ("16-hostile-zero-fill.bin", vec![0; 1024]),
 5529	            ]
 5530	        }
 5531	        other => anyhow::bail!("no classed seed set is defined for {other}"),
 5532	    };
 5533	    for (name, bytes) in seeds {
 5534	        fs::write(dir.join(name), bytes)?;
 5535	    }
 5536	    println!("wrote 16 classed seeds to {dir}");
 5537	    Ok(())
 5538	}
