 5720	    anyhow::ensure!(
 5721	        !proof.build_command.trim().is_empty()
 5722	            && proof.build_command
 5723	                == format!(
 5724	                    "cargo +nightly fuzz build -s {} {}",
 5725	                    row.sanitizer, row.target
 5726	                ),
 5727	        "{}: sanitizer proof build command does not name fuzz build and sanitizer",
 5728	        row.target
 5729	    );
 5730	    anyhow::ensure!(
 5731	        !proof.instrumentation_flags.is_empty()
 5732	            && proof
 5733	                .instrumentation_flags
 5734	                .iter()
