 5736	        "{}: sanitizer proof has no matching instrumentation flag",
 5737	        row.target
 5738	    );
 5739	    anyhow::ensure!(
 5740	        !proof.build_log.trim().is_empty()
 5741	            && !proof.build_log_blake3.trim().is_empty()
 5742	            && !proof.source_commit.trim().is_empty()
 5743	            && !proof.source_tree.trim().is_empty()
 5744	            && !proof.build_result.trim().is_empty(),
 5745	        "{} sanitizer proof lacks current build provenance; regenerate fuzz evidence",
 5746	        row.target
 5747	    );
 5748	    require_eq(
 5749	        &format!("{} sanitizer build_result", row.target),
 5750	        &proof.build_result,
 5751	        "pass",
 5752	    )?;
 5753	    require_eq(
 5754	        &format!("{} sanitizer build_log", row.target),
 5755	        &proof.build_log,
 5756	        &format!("conformance/haqp/evidence/build-logs/{}.log", row.target),
 5757	    )?;
