 5771	        require_eq(
 5772	            &format!("{} sanitizer source_commit/provenance", row.target),
 5773	            &proof.source_commit,
 5774	            &expected.fixed_commit,
 5775	        )?;
 5776	        require_eq(
 5777	            &format!("{} sanitizer source_tree/provenance", row.target),
 5778	            &proof.source_tree,
