 8256	/// The path out of one `git status --porcelain=v1` line.
 8257	///
 8258	/// Not `line[3..]`. `git_text` trims its output, so the FIRST line loses the
 8259	/// leading space of a " M path" status and a fixed three-character slice eats
 8260	/// the first character of its path -- which is how this function first reported
 8261	/// `onformance/haqp/...`. That is the third appearance of this exact off-by-one:
 8262	/// `haqp_flip_packet.py` had it, its local copy in `haqp_blind_review.py` had
 8263	/// it, and it came back here in new code written by someone who knew about both.
 8264	/// Trimming first and splitting on the status field is immune to it.
 8265	fn porcelain_path(line: &str) -> Option<String> {
 8266	    let (_status, rest) = line.trim_start().split_once(' ')?;
 8267	    let path = rest.trim();
 8268	    // Rename and copy entries read "old -> new"; the destination is what is
 8269	    // present in the working tree.
 8270	    let path = path.rsplit(" -> ").next().unwrap_or(path);
 8271	    // Paths containing spaces or non-ASCII come back quoted; the quotes are not
 8272	    // part of the path.
 8273	    let path = path.trim_matches('"');
 8274	    (!path.is_empty()).then(|| path.to_owned())
