 8355	/// word such as `exit` cannot accidentally satisfy a gate row.
 8356	fn has_exact_coordinate_anchor(source: &str, coordinate: &str) -> bool {
 8357	    let coordinate = coordinate.trim();
 8358	    if coordinate.is_empty() {
 8359	        return false;
 8360	    }
 8361	    if coordinate.starts_with("## ") {
 8362	        return source.lines().any(|line| line.trim() == coordinate);
 8363	    }
 8364	    source.lines().any(|line| {
 8365	        line.match_indices(coordinate).any(|(offset, _)| {
 8366	            let before = line[..offset].chars().next_back();
 8367	            let after = line[offset + coordinate.len()..].chars().next();
