 5376	/// Blind pass 1 at 612cbcc (A10): the manifest check counted seeds and hashed
 5377	/// them; sixteen inputs of one class satisfied it. Each tracked seed's name
 5378	/// declares its class through the closed token table above.
 5379	fn verify_seed_classes(root: &Utf8Path, target: &str, seed_dir: &Utf8Path) -> Result<()> {
 5380	    let relative = seed_dir
 5381	        .strip_prefix(root)
 5382	        .map_or_else(|_| seed_dir.to_string(), ToString::to_string);
 5383	    let listed = git_text(root, &["ls-files", "-z", "--", &relative])?;
 5384	    let mut counts = BTreeMap::new();
 5385	    // Blind pass 1 at `6b36bbb9` (A05): the class came from the FILE NAME and
 5386	    // nothing read the bytes, so five copies of one seed under five names
 5387	    // satisfied "seeds spanning valid, boundary, truncated, malformed and
 5388	    // hostile". Content is what makes a seed a seed: two tracked seeds in one
 5389	    // target may not carry the same bytes. Emptiness is not forbidden — an
 5390	    // empty input is a real boundary for a fuzz target, and two targets commit
 5391	    // one on purpose — but it can only be committed once, like anything else.
 5392	    let mut by_digest: BTreeMap<String, String> = BTreeMap::new();
 5393	    for name in listed.split('\0').filter(|name| !name.trim().is_empty()) {
 5394	        let file = Utf8Path::new(name)
 5395	            .file_name()
 5396	            .unwrap_or(name)
 5397	            .to_ascii_lowercase();
 5398	        let bytes = fs::read(root.join(name))
 5399	            .with_context(|| format!("{target}: read committed seed {name}"))?;
 5400	        let digest = blake3::hash(&bytes).to_hex().to_string();
 5401	        if let Some(first) = by_digest.insert(digest, name.to_owned()) {
 5402	            anyhow::bail!(
 5403	                "{target}: committed seeds {first} and {name} carry identical bytes; a class \
 5404	                 spanned by copies of one seed is not a class the corpus covers"
 5405	            );
 5406	        }
 5407	        for (token, holds) in SEED_NAME_PREDICATES {
 5408	            anyhow::ensure!(
 5409	                !file.contains(token) || holds(&bytes),
 5410	                "{target}: seed {name} is named {token:?} and its bytes are not; a class \
 5411	                 witnessed by a mislabelled seed is a class the corpus does not cover"
 5412	            );
 5413	        }
 5414	        let class = SEED_CLASSES
 5415	            .iter()
 5416	            .find(|(_, tokens)| tokens.iter().any(|token| file.contains(token)))
 5417	            .map(|(class, _)| *class)
 5418	            .or_else(|| {
 5419	                SEED_VALID_TOKENS
 5420	                    .iter()
 5421	                    .any(|token| file.contains(token))
 5422	                    .then_some("valid")
 5423	            });
 5424	        if let Some(class) = class {
 5425	            *counts.entry(class).or_insert(0usize) += 1;
 5426	        }
 5427	    }
 5428	    // "valid" is the implicit class of a seed matching no negative token; the
 5429	    // required set is that plus every declared negative class, so adding a
 5430	    // class to the table enforces it.
 5431	    for class in std::iter::once("valid").chain(SEED_CLASSES.iter().map(|(class, _)| *class)) {
 5432	        anyhow::ensure!(
 5433	            counts.get(class).copied().unwrap_or(0) > 0,
 5434	            "{target}: committed seed set has no {class} seed; ADR-0020 §4 requires seeds \
 5435	             spanning valid, boundary, truncated, malformed and hostile input (declared by \
 5436	             name: {:?})",
 5437	            SEED_CLASSES
 5438	                .iter()
 5439	                .map(|(c, t)| (*c, *t))
 5440	                .collect::<Vec<_>>()
 5441	        );
 5442	    }
 5443	    Ok(())
 5444	}
