10995	/// Durable-transition call sites in tracked runtime source, by path.
10996	///
10997	/// Markers are call-shaped for the reason F-34 established for the
10998	/// `skipped-durable-transition` operator: a durable transition is a CALL, and
10999	/// matching bare words lets a rename satisfy the check.
11000	///
11001	/// Enumerated from `git ls-files`, never the filesystem (F-32): a scan that
11002	/// reads the working directory reports a different durable surface on a dirty
11003	/// tree than a fresh clone does, and the clone is the one that has to reproduce
11004	/// this.
11005	///
11006	/// `liminal-xtask` is excluded — the verifier is not runtime code, and its
11007	/// operator table contains the marker as a string literal, so including it
11008	/// would make this count self-referential. `tests/` is excluded: an integration
11009	/// test's commit is not a transition the product performs.
11010	///
11011	/// This is a TRIPWIRE, not a semantic census. It counts call sites textually,
11012	/// including any inside `#[cfg(test)]` modules, and its only job is to fail
11013	/// loudly when the durable surface moves under a disclosure that claims to have
11014	/// surveyed it.
11015	///
11016	/// Known imprecision, and its direction: line comments (`//`, and `///` with
11017	/// them) are skipped, but a marker inside a block comment or a string literal
11018	/// still counts. That errs toward REJECTION — a spurious match fails a packet
11019	/// that was honest, which a human then corrects. The opposite error, silently
11020	/// undercounting, would let a real durable transition hide, so the bias is the
11021	/// one worth having.
11022	/// How many times `line` names one of `symbols` as a durable transition.
11023	///
11024	/// Blind pass 1 at 5fb1b57 (A05): matching `symbol(` missed a turbofish
11025	/// (`rename::<T>(`) and a function pointer (`let f = fs::rename;`). The symbol
11026	/// is matched on a word boundary and accepted when what follows is a call, a
11027	/// path or turbofish, or the end of a value — never when it is more
11028	/// identifier, so `rename_all` and `append_str` are not renames and appends.
11029	/// Counting occurrences rather than marker spellings keeps one call site worth
11030	/// one site however many spellings would match it.
11031	fn durable_symbol_hits(line: &str, symbols: &[String]) -> usize {
11032	    let identifier = |ch: char| ch.is_alphanumeric() || ch == '_';
11033	    let mut hits = 0;
11034	    for symbol in symbols {
11035	        for (offset, _) in line.match_indices(symbol.as_str()) {
11036	            if line[..offset].chars().next_back().is_some_and(identifier) {
11037	                continue;
11038	            }
11039	            let rest = &line[offset + symbol.len()..];
11040	            let follows = rest.starts_with('(')
11041	                || rest.starts_with("::")
11042	                || rest.starts_with(';')
11043	                || rest.starts_with(',')
11044	                || rest.starts_with(')');
11045	            if follows {
11046	                hits += 1;
11047	            }
11048	        }
11049	    }
11050	    hits
11051	}
