11053	fn durable_transition_sites(root: &Utf8Path) -> Result<BTreeMap<String, usize>> {
11054	    // Blind pass 1 at 612cbcc (A05): `inner.log.append(` is the store's durable
11055	    // append (P1-M022 deletes it) and was outside the census, so an append-based
11056	    // transition could move without the scope disclosure noticing.
11057	    // Blind pass 1 at f360e90 (A05): a direct `fs::rename` or `sync_all` is a
11058	    // durable transition with no marker call around it, so it escaped.
11059	    // Blind pass 1 at aa00d41 (A05): `use std::fs::rename as mv; mv(a, b)`
11060	    // named no marker. The durable symbols are matched by name, and a `use`
11061	    // that renames one adds its alias for that file.
11062	    const DURABLE_SYMBOLS: [&str; 6] = [
11063	        "commit",
11064	        "commit_if",
11065	        "append",
11066	        "sync_all",
11067	        "sync_data",
11068	        "rename",
11069	    ];
11070	    let listed = git_text(root, &["ls-files", "-z", "--", "crates"])?;
11071	    let mut sites = BTreeMap::new();
11072	    for name in listed.split('\0').filter(|name| !name.trim().is_empty()) {
11073	        if Utf8Path::new(name).extension() != Some("rs")
11074	            || name.starts_with("crates/liminal-xtask/")
11075	            || name.contains("/tests/")
11076	        {
11077	            continue;
11078	        }
11079	        let path = root.join(name);
11080	        // Never skip a tracked file we cannot read. Dropping it would delete
11081	        // its transitions from the measured surface, and the disclosure would
11082	        // then pass by describing a tree nobody managed to look at — the exact
11083	        // vacuity this check exists to prevent.
11084	        let text = fs::read_to_string(&path).with_context(|| {
11085	            format!(
11086	                "{name} is tracked but unreadable; the durable surface cannot be measured, and \
11087	                 a scope claim over a surface that was not read is worth nothing"
11088	            )
11089	        })?;
11090	        // A `use` that renames a durable symbol makes the alias a marker in
11091	        // this file: `use std::fs::rename as mv;` means `mv` is a rename.
11092	        let mut markers = DURABLE_SYMBOLS
11093	            .iter()
11094	            .map(|symbol| (*symbol).to_owned())
11095	            .collect::<Vec<_>>();
