11100	                }
11101	            }
11102	        }
11103	        let count = text
11104	            .lines()
11105	            // An import declares a name; it performs no transition. Without
11106	            // this the aliasing `use` line counts as a durable call itself.
11107	            .filter(|line| {
11108	                let trimmed = line.trim_start();
11109	                !trimmed.starts_with("//") && !trimmed.starts_with("use ")
11110	            })
11111	            .map(|line| durable_symbol_hits(line, &markers))
11112	            .sum::<usize>();
