11213	                 nor the deferred surface: ADR-0020 §5 exhaustiveness cannot be claimed over a \
11214	                 surface the packet has not surveyed. Register its boundaries or disclose it."
11215	            );
11216	        };
11217	        anyhow::ensure!(
11218	            expected == count,
11219	            "{path}: crash_boundary_scope declares {expected} durable transition(s), source has \
11220	             {count}. The disclosure is stale — a durable surface moved under a claim that says \
11221	             it was surveyed."
