  5301	/// The seed classes ADR-0020 §4 requires a corpus to span, and the closed name
  5302	/// tokens that declare each. A seed matching no negative token is a valid
  5303	/// input by declaration; a corpus needs at least one seed in every class.
  5304	/// What a seed's name asserts about its bytes, where the name asserts anything
  5305	/// checkable. Blind pass 1 at `0a0b4b4b` (A03): the class came from the name
  5306	/// and F-66 added only byte-distinctness, so a valid payload named
  5307	/// `12-invalid-utf8.bin` witnessed the malformed class for five targets — and
  5308	/// five committed seeds were exactly that, their intended `0xff 0xfe` having
  5309	/// been UTF-8 encoded on the way to disk, which is the one thing that makes
  5310	/// those bytes valid. A name that asserts a byte property must exhibit it.
  5311	type SeedPredicate = fn(&[u8]) -> bool;
  5312	
  5313	const SEED_NAME_PREDICATES: [(&str, SeedPredicate); 5] = [
  5314	    ("invalid-utf8", |bytes| std::str::from_utf8(bytes).is_err()),
  5315	    ("empty", |bytes: &[u8]| {
  5316	        bytes.iter().copied().all(|byte| byte.is_ascii_whitespace())
  5317	    }),
  5318	    ("control", |bytes| {
  5319	        bytes
  5320	            .iter()
  5321	            .any(|byte| byte.is_ascii_control() && !byte.is_ascii_whitespace())
  5322	    }),
  5323	    ("unicode", |bytes| {
  5324	        std::str::from_utf8(bytes).is_ok_and(|text| !text.is_ascii())
  5325	    }),
  5326	    ("long-line", |bytes| {
  5327	        bytes
  5328	            .split(|byte| *byte == b'\n')
  5329	            .any(|line| line.len() >= 64)
  5330	    }),
  5331	];
