  5358	const SEED_CLASSES: [(&str, &[&str]); 4] = [
  5359	    ("boundary", &["boundary"]),
  5360	    ("truncated", &["truncated", "unterminated"]),
  5361	    (
  5362	        "malformed",
  5363	        &[
  5364	            "malformed",
  5365	            "invalid",
  5366	            "illegal",
