  5540	/// Digest the seed corpus that is actually COMMITTED (M17.5 F-32).
  5541	///
  5542	/// This read the filesystem and called the result "the committed corpus". It is
  5543	/// not: `.gitignore` excludes `fuzz/corpus/`, so the directory holds sixteen
  5544	/// tracked seeds per target plus every input libFuzzer has written there. The
  5545	/// recorded `seed_count` was therefore a property of ONE MACHINE — 18,233 here
  5546	/// — and a fresh clone, holding the sixteen, could never satisfy it. Killing a
  5547	/// campaign turned a green tree red with no code change.
  5548	///
  5549	/// `git ls-files` fixes it in the direction the error message already claimed,
  5550	/// and sixteen tracked seeds per target is exactly ADR-0020 §4's "at least 16
  5551	/// predeclared seeds".
  5552	fn seed_manifest_digest(root: &Utf8Path, seed_dir: &Utf8Path) -> Result<(u64, String)> {
  5553	    let relative = seed_dir
  5554	        .strip_prefix(root)
  5555	        .unwrap_or(seed_dir)
  5556	        .as_str()
  5557	        .to_owned();
  5558	    let listed = git_text(root, &["ls-files", "-z", "--", &relative])?;
  5559	    let mut files = listed
  5560	        .split('\0')
  5561	        .filter(|name| !name.trim().is_empty())
  5562	        .map(|name| root.join(name))
  5563	        .filter(|path| path.is_file())
  5564	        .collect::<Vec<_>>();
  5565	    anyhow::ensure!(
  5566	        !files.is_empty(),
  5567	        "{seed_dir}: no seed is tracked by git; a corpus that lives only on one \
  5568	         machine cannot reproduce a campaign (ADR-0020 §1)"
  5569	    );
  5570	    files.sort();
  5571	    let mut hasher = blake3::Hasher::new();
  5572	    for path in &files {
  5573	        let name = path
  5574	            .file_name()
  5575	            .with_context(|| format!("{path}: seed has no file name"))?;
  5576	        let bytes = fs::read(path).with_context(|| format!("read fuzz seed {path}"))?;
  5577	        let mut seed_hash = Sha256::new();
  5578	        seed_hash.update(bytes);
  5579	        let seed_hash = format!("{:x}", seed_hash.finalize());
  5580	        hasher.update(name.as_bytes());
  5581	        hasher.update(&[0]);
  5582	        hasher.update(seed_hash.as_bytes());
  5583	        hasher.update(&[0]);
  5584	    }
  5585	    Ok((
  5586	        u64::try_from(files.len()).context("fuzz seed count exceeds u64")?,
  5587	        hasher.finalize().to_hex().to_string(),
  5588	    ))
  5589	}
