  8091	
  8092	/// ADR-0020 §1: the qualification lane runs from ONE fixed clean commit and
  8093	/// tree. The packet is committed one commit after that fixed evidence commit;
  8094	/// requiring the packet's metadata commit to equal HEAD would be a
  8095	/// self-referential hash claim and cannot be satisfied by Git.
  8096	fn verify_provenance(root: &Utf8Path, packet: &Packet) -> Result<()> {
  8097	    let Some(provenance) = &packet.provenance else {
  8098	        anyhow::bail!("packet has no provenance block; qualification is unbound to any tree");
  8099	    };
  8100	    let git = |args: &[&str]| -> Result<String> {
  8101	        let out = Command::new("git").current_dir(root).args(args).output()?;
  8102	        anyhow::ensure!(out.status.success(), "git {args:?} failed");
  8103	        Ok(String::from_utf8(out.stdout)?.trim().to_owned())
  8104	    };
  8105	    require_eq(
  8106	        "provenance.commit/fixed_commit",
  8107	        &provenance.commit,
  8108	        &provenance.fixed_commit,
  8109	    )?;
  8110	    let parent = git(&["rev-parse", "HEAD^"])?;
  8111	    let parents = git(&["rev-list", "--parents", "-n1", "HEAD"])?
  8112	        .split_whitespace()
  8113	        .count()
  8114	        .saturating_sub(1);
  8115	    anyhow::ensure!(
  8116	        parents == 1,
  8117	        "qualification metadata commit must have exactly one parent, found {parents}"
  8118	    );
  8119	    require_eq(
  8120	        "provenance.evidence_parent",
  8121	        &provenance.evidence_parent,
  8122	        &parent,
  8123	    )?;
  8124	    require_eq(
  8125	        "provenance.fixed_commit/evidence_parent",
  8126	        &provenance.fixed_commit,
  8127	        &provenance.evidence_parent,
  8128	    )?;
  8129	    // The metadata child may carry only qualification outputs. If source or
  8130	    // gate code changes after evidence was captured, the packet can still
  8131	    // point at the old tree while claiming the new behavior was tested.
  8132	    let changed = git_text(
  8133	        root,
  8134	        &[
  8135	            "diff",
  8136	            "--name-only",
  8137	            &format!("{}..HEAD", provenance.evidence_parent),
  8138	        ],
  8139	    )?;
  8140	    for path in changed.lines().filter(|path| !path.trim().is_empty()) {
  8141	        if path == PHASE0_GATE_FILE {
  8142	            verify_gate_unignore_only(root, &provenance.evidence_parent)?;
  8143	            continue;
  8144	        }
  8145	        anyhow::ensure!(
  8146	            qualification_metadata_path(path),
  8147	            "qualification metadata child changed non-metadata path {path:?}; source and gate code must remain at fixed commit"
  8148	        );
  8149	    }
  8150	    let fixed_tree = git(&[
  8151	        "rev-parse",
  8152	        &format!("{}^{{tree}}", provenance.fixed_commit),
  8153	    ])?;
  8154	    require_eq("provenance.fixed_tree", &provenance.fixed_tree, &fixed_tree)?;
  8155	    let dirty = git(&["status", "--porcelain"])?;
  8156	    anyhow::ensure!(
  8157	        dirty.is_empty(),
  8158	        "qualification requires a clean tree; {} path(s) are dirty",
  8159	        dirty.lines().count()
  8160	    );
  8161	    let lockfile = fs::read(root.join("Cargo.lock"))?;
  8162	    let digest = blake3::hash(&lockfile).to_hex().to_string();
  8163	    require_eq(
  8164	        "provenance.lockfile_blake3",
  8165	        &provenance.lockfile_blake3,
  8166	        &digest,
  8167	    )?;
  8168	    Ok(())
  8169	}
