  8171	/// The one gate whose `#[ignore]` the metadata child may lift (AM-17.6).
  8172	const PHASE0_GATE_FILE: &str = "conformance/tests/phase0.rs";
  8173	const PHASE0_GATE_IGNORE: &str =
  8174	    r#"#[ignore = "Phase 0 M17: HAQP qualification evidence not yet complete"]"#;
  8175	
  8176	/// The metadata child may lift EXACTLY ONE `#[ignore]`, and change nothing else
  8177	/// (AM-17.6).
  8178	///
  8179	/// `phase1_suite_packet_is_complete_and_unratified` is M17.5's stated exit gate,
  8180	/// and it asserts that the packet is complete. It therefore cannot be live
  8181	/// before the flip that completes the packet — un-ignoring it at the fixed base
  8182	/// commits a red tree, and un-ignoring it after the flip moves HEAD and breaks
  8183	/// `evidence_parent == HEAD^`. The child is the only place it can go.
  8184	///
  8185	/// Widening the path allowlist alone would let gate LOGIC change in the child,
  8186	/// which is the whole thing `verify_provenance` exists to prevent. So the diff
  8187	/// itself is checked: one removed line, no added lines, and the removed line is
  8188	/// that attribute. Anything else in this file is refused exactly as before.
  8189	fn verify_gate_unignore_only(root: &Utf8Path, evidence_parent: &str) -> Result<()> {
  8190	    let diff = git_text(
  8191	        root,
  8192	        &[
  8193	            "diff",
  8194	            "--unified=0",
  8195	            &format!("{evidence_parent}..HEAD"),
  8196	            "--",
  8197	            PHASE0_GATE_FILE,
  8198	        ],
  8199	    )?;
  8200	    let mut removed = Vec::new();
  8201	    let mut added = Vec::new();
  8202	    for line in diff.lines() {
  8203	        if line.starts_with("+++") || line.starts_with("---") {
  8204	            continue;
  8205	        }
  8206	        if let Some(rest) = line.strip_prefix('-') {
  8207	            removed.push(rest.trim().to_owned());
  8208	        } else if let Some(rest) = line.strip_prefix('+') {
  8209	            added.push(rest.trim().to_owned());
  8210	        }
  8211	    }
  8212	    anyhow::ensure!(
  8213	        added.is_empty(),
  8214	        "the metadata child added {} line(s) to {PHASE0_GATE_FILE}; it may only lift the \
  8215	         qualification gate's #[ignore], never add gate code: {added:?}",
  8216	        added.len()
  8217	    );
  8218	    anyhow::ensure!(
  8219	        removed.len() == 1,
  8220	        "the metadata child removed {} line(s) from {PHASE0_GATE_FILE}; exactly one \
  8221	         #[ignore] may be lifted: {removed:?}",
  8222	        removed.len()
  8223	    );
  8224	    require_eq(
  8225	        "metadata child's lifted attribute",
  8226	        removed[0].as_str(),
  8227	        PHASE0_GATE_IGNORE,
  8228	    )
  8229	}
