  8231	/// Working-tree paths that are neither qualification metadata nor evidence.
  8232	///
  8233	/// A blanket `git status --porcelain` check is wrong here and has now been wrong
  8234	/// four times: once each in haqp_flip_packet.py, haqp_blind_review.py and
  8235	/// haqp_campaign_clock.sh, and here. The lanes WRITE evidence as they run, so by
  8236	/// the time the mutant stage starts, `canaries.json`, `generated.json` and
  8237	/// `crash.json` are already modified. The blanket check then refused a tree that
  8238	/// was doing exactly what the lane asked of it -- and the qualify script's
  8239	/// "not-ready is tolerated" branch read the STALE file, so the failure passed
  8240	/// silently and mutants.json kept an August commit.
  8241	///
  8242	/// `scripts/haqp_paths.py` is the sibling rule for the shell lanes. They agree
  8243	/// except on `conformance/tests/phase0.rs`, deliberately: the Python side runs
  8244	/// at FLIP time, after AM-17.6 has lifted the gate's `#[ignore]`, so that file
  8245	/// is legitimately modified by then. Here the check runs mid-campaign, before
  8246	/// the flip, where a modified gate file means someone edited gate code while
  8247	/// evidence was being produced -- which must invalidate the run.
  8248	fn source_dirt(root: &Utf8Path) -> Result<Vec<String>> {
  8249	    Ok(git_text(root, &["status", "--porcelain=v1"])?
  8250	        .lines()
  8251	        .filter_map(porcelain_path)
  8252	        .filter(|path| !qualification_metadata_path(path))
  8253	        .collect())
  8254	}
  8255	
  8256	/// The path out of one `git status --porcelain=v1` line.
  8257	///
  8258	/// Not `line[3..]`. `git_text` trims its output, so the FIRST line loses the
  8259	/// leading space of a " M path" status and a fixed three-character slice eats
  8260	/// the first character of its path -- which is how this function first reported
  8261	/// `onformance/haqp/...`. That is the third appearance of this exact off-by-one:
  8262	/// `haqp_flip_packet.py` had it, its local copy in `haqp_blind_review.py` had
  8263	/// it, and it came back here in new code written by someone who knew about both.
  8264	/// Trimming first and splitting on the status field is immune to it.
  8265	fn porcelain_path(line: &str) -> Option<String> {
  8266	    let (_status, rest) = line.trim_start().split_once(' ')?;
  8267	    let path = rest.trim();
  8268	    // Rename and copy entries read "old -> new"; the destination is what is
  8269	    // present in the working tree.
  8270	    let path = path.rsplit(" -> ").next().unwrap_or(path);
  8271	    // Paths containing spaces or non-ASCII come back quoted; the quotes are not
  8272	    // part of the path.
  8273	    let path = path.trim_matches('"');
  8274	    (!path.is_empty()).then(|| path.to_owned())
  8275	}
