  8277	/// Read one evidence artifact, transparently decompressing `.zst`.
  8278	///
  8279	/// A full 30-minute ASan campaign emits gigabytes of strace output — the
  8280	/// 2026-09-02 run produced a 1.56 GB trace for `graph_interchange_codec`, which
  8281	/// no remote will accept. zstd takes that to roughly 55 MB, and `zstd` is
  8282	/// already a workspace dependency used for exactly this under AM-11.6.
  8283	///
  8284	/// The digest is taken over the DECOMPRESSED bytes, which diverges from
  8285	/// AM-11.6 deliberately. AM-11.6 freezes the compressed artifact; here
  8286	/// `trace_blake3` already means "digest of the trace this campaign produced",
  8287	/// and keeping that meaning leaves every existing check saying exactly what it
  8288	/// said before. It also survives a zstd upgrade: the attestation is over
  8289	/// content, not over an encoding.
  8290	fn read_evidence_bytes(path: &Utf8Path) -> Result<Vec<u8>> {
  8291	    if path.extension() == Some("zst") {
  8292	        let file = fs::File::open(path).with_context(|| format!("open {path}"))?;
  8293	        zstd::decode_all(std::io::BufReader::new(file))
  8294	            .with_context(|| format!("{path}: evidence is not valid zstd"))
  8295	    } else {
  8296	        fs::read(path).with_context(|| format!("read {path}"))
  8297	    }
  8298	}
