13191	/// Family 1 — graph/interchange codecs.
13192	///
13193	/// Metamorphic relation: **byte-canonical stability**. Re-serializing a value
13194	/// decoded from canonical bytes must reproduce those bytes exactly. The
13195	/// comparison is over BYTES, never the type's own `PartialEq`, so a broken
13196	/// `Eq` cannot make this pass (ADR-0020 §5).
13197	fn case_interchange(rng: &mut Rng) -> Result<Case> {
13198	    use liminal_graph::Node;
13199	
13200	    let category = rng.category("graph/interchange codecs");
13201	    let malformed = matches!(
13202	        category,
13203	        "empty"
13204	            | "duplicate-id"
13205	            | "missing-node"
13206	            | "cycle"
13207	            | "unknown-kind"
13208	            | "external-value"
13209	            | "comment"
13210	            | "truncated-json"
13211	            | "invalid-json"
13212	            | "hostile"
13213	    );
13214	    if malformed {
13215	        let raw = match category {
13216	            "empty" => Vec::new(),
13217	            "duplicate-id" => br#"{"id":"00000000-0000-0000-0000-000000000001","id":"00000000-0000-0000-0000-000000000002","kind":1,"payload":"none","revision":0,"flags":0}"#.to_vec(),
13218	            "missing-node" => br"{}".to_vec(),
13219	            "cycle" => br#"{"id":"00000000-0000-0000-0000-000000000001","kind":1,"payload":{"cycle":["a","b","a"]},"revision":0,"flags":0}"#.to_vec(),
13220	            "unknown-kind" => br#"{"id":"00000000-0000-0000-0000-000000000001","kind":"unknown","payload":"none","revision":0,"flags":0}"#.to_vec(),
13221	            "external-value" => br#"{"id":"00000000-0000-0000-0000-000000000001","kind":1,"payload":{"external-value":"source"},"revision":0,"flags":0}"#.to_vec(),
13222	            "comment" => br#"{"id":"00000000-0000-0000-0000-000000000001","kind":1,"payload":{"comment":"note"},"revision":0,"flags":0}"#.to_vec(),
13223	            "truncated-json" => format!(r#"{{"category":"{category}""#).into_bytes(),
13224	            "invalid-json" => {
13225	                let mut bytes = format!("{category}\0").into_bytes();
13226	                bytes.push(0xff);
13227	                bytes
13228	            }
13229	            "hostile" => vec![0, 0xff, 0x7f],
13230	            _ => unreachable!("unknown graph negative category {category}"),
13231	        };
13232	        anyhow::ensure!(
13233	            serde_json::from_slice::<Node>(&raw).is_err(),
13234	            "graph negative category {category} unexpectedly decoded"
13235	        );
13236	        let witness = if raw.is_empty() {
13237	            format!("{category}:empty").into_bytes()
13238	        } else {
13239	            raw
13240	        };
13241	        return Ok(Case::Negative { category, witness });
13242	    }
13243	    // Blind pass 1 at 612cbcc (A07): every accepted category built one Node
13244	    // with the category's name leaked into its payload, and a Node is not even
13245	    // the codec's unit — the fuzz target decodes a Transaction. Each category
13246	    // now builds the transaction shape it names, and the oracle counts that
13247	    // shape in the encoded JSON independently of the codec's own equality.
13248	    let text = format!("{category}:{}", rng.word());
13249	    let durable = rng.below(2) == 1;
13250	    if matches!(category, "single-node") && durable && text.trim().is_empty() {
13251	        return Ok(Case::Discarded {
13252	            category,
13253	            witness: format!("durable-without-payload:{text:?}").into_bytes(),
13254	        });
13255	    }
13256	    let (txn, shape) = interchange_transaction(category, rng, &text, durable);
13257	    let once = serde_json::to_vec(&txn)?;
13258	    let decoded: liminal_graph::Transaction = serde_json::from_slice(&once)?;
13259	    let twice = serde_json::to_vec(&decoded)?;
13260	    let witness = independent_oracle_interchange(&txn, &decoded, &once, &twice, shape)?;
13261	    Ok(Case::Accepted { category, witness })
13262	}
