 5591	fn verify_fuzz_rows(recorded: &[FuzzEvidence], present: &BTreeSet<String>) -> Result<()> {
 5592	    let declared = recorded
 5593	        .iter()
 5594	        .map(|row| row.target.clone())
 5595	        .collect::<BTreeSet<_>>();
 5596	    if &declared != present {
 5597	        anyhow::bail!(
 5598	            "fuzz evidence does not cover the targets in the tree: recorded={declared:?}, \
 5599	             present={present:?}"
 5600	        );
 5601	    }
 5602	    require_unique(
 5603	        recorded.iter().map(|row| row.target.as_str()),
 5604	        "fuzz target",
 5605	    )?;
 5606	
 5607	    // M17.5 F-17: `log` names a gitignored path, so the counts it would
 5608	    // substantiate were unfalsifiable once the run ended. The digest makes a
 5609	    // later-produced log checkable.
 5610	    for row in recorded {
 5611	        if row.log_blake3.len() != 64 || !row.log_blake3.chars().all(|c| c.is_ascii_hexdigit()) {
 5612	            anyhow::bail!(
 5613	                "{}: log_blake3 {:?} is not a 64-hex digest, so its log can never be checked",
 5614	                row.target,
 5615	                row.log_blake3
 5616	            );
 5617	        }
 5618	    }
 5619	
 5620	    // M17.5 F-27 / P1-A09: ADR-0020 §4 requires a SANITIZER-ENABLED campaign
 5621	    // and the evidence had no way to say whether one ran. An unsanitized
 5622	    // campaign finds crashes it can see and silently misses every
 5623	    // memory-safety defect it cannot.
 5624	    for row in recorded {
 5625	        if !matches!(
 5626	            row.sanitizer.as_str(),
 5627	            "address" | "memory" | "thread" | "leak"
 5628	        ) {
 5629	            anyhow::bail!(
 5630	                "{}: sanitizer {:?} is not a sanitizer ADR-0020 §4 accepts",
 5631	                row.target,
 5632	                row.sanitizer
 5633	            );
 5634	        }
 5635	    }
 5636	
 5637	    let total_minutes: u64 = recorded.iter().map(|row| row.seconds / 60).sum();
 5638	    if total_minutes < 150 {
 5639	        anyhow::bail!("recorded fuzz budget {total_minutes} target-minutes is below 150");
 5640	    }
 5641	    for row in recorded {
 5642	        if row.exit_code != 0 {
 5643	            anyhow::bail!(
 5644	                "fuzz target {} exited {} with {} artifact(s) — every crash is a failing \
 5645	                 result (ADR-0020 §4)",
 5646	                row.target,
 5647	                row.exit_code,
 5648	                row.artifacts
 5649	            );
 5650	        }
 5651	        if row.artifacts != 0 {
 5652	            anyhow::bail!(
 5653	                "fuzz target {} left {} artifacts",
 5654	                row.target,
 5655	                row.artifacts
 5656	            );
 5657	        }
 5658	        if row.execs == 0 {
 5659	            anyhow::bail!("fuzz target {} recorded zero executions", row.target);
 5660	        }
 5661	        if row.log.trim().is_empty() {
 5662	            anyhow::bail!("fuzz target {} records no log path", row.target);
 5663	        }
 5664	        // ADR-0020 line 90: "each family also receives one 30-minute
 5665	        // sanitizer-enabled fuzz campaign". That is a per-target floor, not just
 5666	        // a contribution to the 150 target-minute total — without it one long
 5667	        // target could carry the sum while another ran for seconds.
 5668	        //
 5669	        // The same 30-minute floor is used by family budget reconciliation.
