 9003	        "disabled-crash-point",
 9004	        "ordering-nondeterminism",
 9005	        "oracle-short-circuit",
 9006	        "broadened-allow-list",
 9007	    ];
 9008	    for (family, count) in by_family {
 9009	        if *count != 13 {
 9010	            anyhow::bail!("family {family} mutant count must be 13, got {count}");
 9011	        }
 9012	    }
 9013	    for (operator, count) in by_operator {
